"""The ``stockroom`` command line."""

from __future__ import annotations

import csv
import io
import json
import os
import re
import sys
from decimal import Decimal
from typing import Dict, List, Optional, Sequence, Tuple

from . import orders as orders_mod
from . import shelves
from .model import Movement, Order, ParseError, Product, Quote
from .parse import first_negative, parse_catalog, parse_date, parse_movements, parse_orders
from .pricing import price_order

USAGE = (
    "usage: stockroom [--dir DIR] COMMAND ...\n"
    "  stock [--json] | low [--json] | history SKU [--json]\n"
    "  receive DATE SKU QUANTITY [NOTE] | ship DATE SKU QUANTITY [NOTE]\n"
    "  quote ORDER [--json] | fulfil ORDER DATE | invoice ORDER [--json]\n"
    "  report [--format text|csv|json]"
)

CATALOG, MOVEMENTS, ORDERS = "catalog.txt", "movements.txt", "orders.txt"

# command -> (files read, min positionals, max positionals, flag options)
_COMMANDS = {
    "stock": ((CATALOG, MOVEMENTS), 0, 0, ("--json",)),
    "low": ((CATALOG, MOVEMENTS), 0, 0, ("--json",)),
    "history": ((CATALOG, MOVEMENTS), 1, 1, ("--json",)),
    "receive": ((CATALOG, MOVEMENTS), 3, 4, ()),
    "ship": ((CATALOG, MOVEMENTS), 3, 4, ()),
    "quote": ((CATALOG, ORDERS), 1, 1, ("--json",)),
    "fulfil": ((CATALOG, MOVEMENTS, ORDERS), 2, 2, ()),
    "invoice": ((CATALOG, MOVEMENTS, ORDERS), 1, 1, ("--json",)),
    "report": ((CATALOG, MOVEMENTS, ORDERS), 0, 0, ()),
}
_RAW_ARGS = ("receive", "ship", "fulfil")  # every non --dir argument is positional
_FORMATS = ("text", "csv", "json")
_UINT = re.compile(r"[0-9]+")


class CliError(Exception):
    """Stop with this exit status and message on stderr."""

    def __init__(self, code: int, message: str):
        super().__init__(message)
        self.code = code
        self.message = message


class _Args:
    def __init__(self) -> None:
        self.directory = "."
        self.command = ""
        self.positional: List[str] = []
        self.json = False
        self.format = "text"


def _usage_error(message: str) -> CliError:
    return CliError(2, "%s\n%s" % (message, USAGE))


def _extract_dir(argv: Sequence[str]) -> Tuple[str, List[str]]:
    """Pull out every --dir DIR / --dir=DIR (last wins); return (dir, the rest)."""
    directory = "."
    rest: List[str] = []
    i = 0
    while i < len(argv):
        arg = argv[i]
        if arg == "--dir":
            if i + 1 >= len(argv):
                raise _usage_error("option --dir needs a value")
            directory = argv[i + 1]
            i += 2
            continue
        if arg.startswith("--dir="):
            directory = arg[len("--dir="):]
        else:
            rest.append(arg)
        i += 1
    return directory, rest


def parse_args(argv: Sequence[str]) -> _Args:
    args = _Args()
    args.directory, rest = _extract_dir(argv)
    if not rest:
        raise _usage_error("no command given")
    name = rest[0]
    if name not in _COMMANDS:
        raise _usage_error("unknown command %r" % name)
    args.command = name
    _, low, high, flags = _COMMANDS[name]
    items = rest[1:]
    if name in _RAW_ARGS:
        args.positional = list(items)
    else:
        i = 0
        while i < len(items):
            arg = items[i]
            if name == "report" and arg == "--format":
                if i + 1 >= len(items):
                    raise _usage_error("option --format needs a value")
                args.format = items[i + 1]
                i += 2
                continue
            if name == "report" and arg.startswith("--format="):
                args.format = arg[len("--format="):]
            elif arg in flags:
                args.json = True
            elif arg.startswith("-") and arg != "-":
                raise _usage_error("unknown option %r for %s" % (arg, name))
            else:
                args.positional.append(arg)
            i += 1
        if args.format not in _FORMATS:
            raise _usage_error("bad --format %r (want text, csv or json)" % args.format)
    if not low <= len(args.positional) <= high:
        raise _usage_error("wrong number of arguments for %s" % name)
    if name in ("receive", "ship", "fulfil"):
        raw_date = args.positional[0] if name != "fulfil" else args.positional[1]
        try:
            parse_date(raw_date)
        except ValueError:
            raise _usage_error("bad date %r (want a real YYYY-MM-DD date)" % raw_date) from None
    return args


# ---------------------------------------------------------------- reading files


def _read(directory: str, name: str, required: bool) -> str:
    path = os.path.join(directory, name)
    try:
        with open(path, "rb") as handle:
            data = handle.read()
    except FileNotFoundError:
        if required:
            raise CliError(2, "%s: file not found" % name) from None
        return ""
    except OSError as exc:
        raise CliError(2, "%s: cannot read: %s" % (name, exc.strerror or exc)) from None
    try:
        return data.decode("utf-8")
    except UnicodeDecodeError:
        raise CliError(2, "%s: not valid UTF-8" % name) from None


def _parsed(name: str, func, *args):
    try:
        return func(*args)
    except ParseError as exc:
        exc.file = name
        raise CliError(1, "%s: %s" % (name, exc)) from None


class _Data:
    """Files a command needs, read first (exit 2), then parsed (exit 1)."""

    def __init__(self, directory: str, files: Sequence[str]) -> None:
        if not os.path.isdir(directory):
            raise CliError(2, "%s: not a folder" % directory)
        texts = {name: _read(directory, name, name == CATALOG) for name in files}
        self.directory = directory
        self.catalog: Dict[str, Product] = _parsed(CATALOG, parse_catalog, texts[CATALOG])
        self.movements: List[Movement] = []
        self.orders: List[Order] = []
        if MOVEMENTS in texts:
            self.movements = _parsed(MOVEMENTS, parse_movements, texts[MOVEMENTS], self.catalog)
        if ORDERS in texts:
            self.orders = _parsed(ORDERS, parse_orders, texts[ORDERS], self.catalog)

    def order(self, wanted: str) -> Order:
        for order in self.orders:
            if order.id == wanted.upper():
                return order
        raise CliError(1, "unknown order %s" % wanted)


# ---------------------------------------------------------------- formatting


def _money(value: Decimal) -> str:
    return format(value, "f")


def _json(value) -> str:
    return json.dumps(value, indent=2, ensure_ascii=False) + "\n"


def _lines(rows: List[str]) -> str:
    return "".join(row + "\n" for row in rows)


def _delta(quantity: int) -> str:
    return "%+d" % quantity


def _movement_line(m: Movement) -> str:
    text = "%s %s %s" % (m.date.isoformat(), m.sku, _delta(m.quantity))
    return text + (" " + m.note if m.note else "")


# ---------------------------------------------------------------- shelves commands


def cmd_stock(data: _Data, args: _Args) -> str:
    levels = shelves.stock_levels(data.catalog, data.movements)
    rows = []
    for sku in sorted(data.catalog):
        product = data.catalog[sku]
        rows.append((product, levels[sku], shelves.status(product, levels[sku])))
    if args.json:
        return _json(
            [
                {"sku": p.sku, "name": p.name, "onhand": onhand, "status": status}
                for p, onhand, status in rows
            ]
        )
    return _lines(["%s %d %s %s" % (p.sku, onhand, st, p.name) for p, onhand, st in rows])


def cmd_low(data: _Data, args: _Args) -> str:
    levels = shelves.stock_levels(data.catalog, data.movements)
    rows = []
    for sku in sorted(data.catalog):
        product = data.catalog[sku]
        if shelves.status(product, levels[sku]) != "ok":
            rows.append((sku, levels[sku], product.reorder, shelves.buy_quantity(product, levels[sku])))
    if args.json:
        return _json(
            [{"sku": s, "onhand": o, "reorder": r, "buy": b} for s, o, r, b in rows]
        )
    return _lines(["%s %d %d %d" % row for row in rows])


def cmd_history(data: _Data, args: _Args) -> str:
    sku = args.positional[0].upper()
    if sku not in data.catalog:
        raise CliError(1, "unknown SKU %s" % args.positional[0])
    entries = shelves.history(sku, data.movements)
    if args.json:
        return _json(
            [
                {
                    "date": m.date.isoformat(),
                    "delta": _delta(m.quantity),
                    "balance": balance,
                    "note": m.note,
                }
                for m, balance in entries
            ]
        )
    rows = []
    for m, balance in entries:
        row = "%s %s %d" % (m.date.isoformat(), _delta(m.quantity), balance)
        rows.append(row + (" " + m.note if m.note else ""))
    return _lines(rows)


def _append(data: _Data, new: List[Movement]) -> None:
    """Append movement lines to movements.txt in one write (adds a missing final newline)."""
    path = os.path.join(data.directory, MOVEMENTS)
    text = "".join(_movement_line(m) + "\n" for m in new)
    try:
        payload = text.encode("utf-8")
    except UnicodeEncodeError:
        raise CliError(1, "note is not valid text") from None
    try:
        prefix = b""
        try:
            with open(path, "rb") as handle:
                handle.seek(0, os.SEEK_END)
                if handle.tell() > 0:
                    handle.seek(-1, os.SEEK_END)
                    if handle.read(1) != b"\n":
                        prefix = b"\n"
        except FileNotFoundError:
            pass
        with open(path, "ab") as handle:
            handle.write(prefix + payload)
    except OSError as exc:
        raise CliError(2, "%s: cannot write: %s" % (MOVEMENTS, exc.strerror or exc)) from None


def cmd_move(data: _Data, args: _Args) -> str:
    sign = 1 if args.command == "receive" else -1
    raw_date, raw_sku, raw_qty = args.positional[:3]
    note = args.positional[3].strip(" \t") if len(args.positional) == 4 else ""
    sku = raw_sku.upper()
    if sku not in data.catalog:
        raise CliError(1, "unknown SKU %s" % raw_sku)
    if not _UINT.fullmatch(raw_qty) or len(raw_qty) > 18 or int(raw_qty) < 1:
        raise CliError(1, "bad quantity %r (want a whole number of 1 or more)" % raw_qty)
    if "\n" in note or "\r" in note:
        raise CliError(1, "note may not contain a line break")
    move = Movement(parse_date(raw_date), sku, sign * int(raw_qty), note)
    bad = first_negative(data.movements + [move])
    if bad is not None:
        culprit = (data.movements + [move])[bad]
        raise CliError(
            1,
            "refused: stock of %s would go below zero on %s"
            % (culprit.sku, culprit.date.isoformat()),
        )
    _append(data, [move])
    return _movement_line(move) + "\n"


# ---------------------------------------------------------------- orders commands


def _quote_rows(order: Order, quote: Quote, prefix: str = "") -> List[str]:
    rows = ["%s%s %s %s" % (prefix, order.id, order.date.isoformat(), order.customer)]
    for ln in quote.lines:
        rows.append(
            "%s %d %s %s %s %s"
            % (ln.sku, ln.quantity, _money(ln.unit), _money(ln.gross), _money(ln.discount), _money(ln.net))
        )
    rows.append("subtotal " + _money(quote.subtotal))
    rows.append("order discount " + _money(quote.order_discount))
    rows.append("tax " + _money(quote.tax))
    rows.append("total " + _money(quote.total))
    return rows


def _quote_json(order: Order, quote: Quote) -> str:
    return _json(
        {
            "order": order.id,
            "date": order.date.isoformat(),
            "customer": order.customer,
            "lines": [
                {
                    "sku": ln.sku,
                    "quantity": ln.quantity,
                    "unit": _money(ln.unit),
                    "gross": _money(ln.gross),
                    "discount": _money(ln.discount),
                    "net": _money(ln.net),
                }
                for ln in quote.lines
            ],
            "subtotal": _money(quote.subtotal),
            "order_discount": _money(quote.order_discount),
            "tax": _money(quote.tax),
            "total": _money(quote.total),
        }
    )


def cmd_quote(data: _Data, args: _Args) -> str:
    order = data.order(args.positional[0])
    quote = price_order(order, data.catalog)
    if args.json:
        return _quote_json(order, quote)
    return _lines(_quote_rows(order, quote))


def cmd_invoice(data: _Data, args: _Args) -> str:
    order = data.order(args.positional[0])
    shipped = orders_mod.shipped_quantities(order, data.movements)
    if not any(shipped):
        raise CliError(1, "nothing shipped for %s yet" % order.id)
    billed = orders_mod.shipped_order(order, shipped)
    quote = price_order(billed, data.catalog)
    if args.json:
        return _quote_json(billed, quote)
    return _lines(_quote_rows(billed, quote, "invoice "))


def cmd_fulfil(data: _Data, args: _Args) -> str:
    order = data.order(args.positional[0])
    date = parse_date(args.positional[1])
    if date < order.date:
        raise CliError(
            1,
            "refused: %s is before the order date %s" % (date.isoformat(), order.date.isoformat()),
        )
    plan = orders_mod.fulfil_plan(order, date, data.movements)
    new = [
        Movement(date, sku, -now, "order %s" % order.id) for sku, now, _ in plan if now > 0
    ]
    if new:
        _append(data, new)
    shipped = orders_mod.shipped_quantities(order, data.movements + new)
    rows = ["%s shipped %d backordered %d" % row for row in plan]
    rows.append("status " + orders_mod.order_status(order, shipped))
    return _lines(rows)


_REPORT_KEYS = ("order", "date", "customer", "status", "ordered", "shipped", "quoted", "invoiced")


def cmd_report(data: _Data, args: _Args) -> str:
    rows = []
    for order in sorted(data.orders, key=lambda o: (o.date, o.id)):
        shipped = orders_mod.shipped_quantities(order, data.movements)
        quoted = price_order(order, data.catalog).total
        invoiced = Decimal("0.00")
        if any(shipped):
            billed = orders_mod.shipped_order(order, shipped)
            invoiced = price_order(billed, data.catalog).total
        rows.append(
            (
                order.id,
                order.date.isoformat(),
                order.customer,
                orders_mod.order_status(order, shipped),
                sum(q for _, q in order.lines),
                sum(shipped),
                _money(quoted),
                _money(invoiced),
            )
        )
    if args.format == "json":
        return _json([dict(zip(_REPORT_KEYS, row)) for row in rows])
    if args.format == "csv":
        buffer = io.StringIO()
        writer = csv.writer(buffer, lineterminator="\n")
        writer.writerow(_REPORT_KEYS)
        writer.writerows(rows)
        return buffer.getvalue()
    return _lines(
        ["%s %s %s %s %d/%d %s %s" % (r[0], r[1], r[2], r[3], r[5], r[4], r[6], r[7]) for r in rows]
    )


_HANDLERS = {
    "stock": cmd_stock,
    "low": cmd_low,
    "history": cmd_history,
    "receive": cmd_move,
    "ship": cmd_move,
    "quote": cmd_quote,
    "fulfil": cmd_fulfil,
    "invoice": cmd_invoice,
    "report": cmd_report,
}


# ---------------------------------------------------------------- entry point


def _write_stdout(text: str) -> None:
    stream = sys.stdout
    buffer = getattr(stream, "buffer", None)
    if buffer is not None:
        buffer.write(text.encode("utf-8"))
        buffer.flush()
    else:
        stream.write(text)
        stream.flush()


def _silence_stdout() -> None:
    try:
        devnull = os.open(os.devnull, os.O_WRONLY)
        os.dup2(devnull, sys.stdout.fileno())
    except (OSError, ValueError, AttributeError, io.UnsupportedOperation):
        pass


def main(argv: Optional[Sequence[str]] = None) -> int:
    if argv is None:
        argv = sys.argv[1:]
    try:
        args = parse_args(list(argv))
        files = _COMMANDS[args.command][0]
        data = _Data(args.directory, files)
        output = _HANDLERS[args.command](data, args)
    except CliError as exc:
        sys.stderr.write("stockroom: %s\n" % exc.message)
        return exc.code
    try:
        if output:
            _write_stdout(output)
    except BrokenPipeError:
        _silence_stdout()
    return 0

