def cmd_report(data: _Data, args: _Args) -> str:
    rows = []
    for order in sorted(data.orders, key=lambda o: (o.date, o.id)):
        shipped = orders_mod.shipped_quantities(order, data.movements)
        quoted = price_order(order, data.catalog).total
        invoiced = Decimal("0.00")
        if any(shipped):
            billed = orders_mod.shipped_order(order, shipped)
            invoiced = price_order(billed, data.catalog).total
        rows.append(
            (
                order.id,
                order.date.isoformat(),
                order.customer,
                orders_mod.order_status(order, shipped),
                sum(q for _, q in order.lines),
                sum(shipped),
                _money(quoted),
                _money(invoiced),
            )
        )
    if args.format == "json":
        return _json([dict(zip(_REPORT_KEYS, row)) for row in rows])
    if args.format == "csv":
        buffer = io.StringIO()
        writer = csv.writer(buffer, lineterminator="\n")
        writer.writerow(_REPORT_KEYS)
        writer.writerows(rows)
        return buffer.getvalue()
    return _lines(
        ["%s %s %s %s %d/%d %s %s" % (r[0], r[1], r[2], r[3], r[5], r[4], r[6], r[7]) for r in rows]
    )


_HANDLERS = {
    "stock": cmd_stock,
    "low": cmd_low,
    "history": cmd_history,
    "receive": cmd_move,
    "ship": cmd_move,
    "quote": cmd_quote,
    "fulfil": cmd_fulfil,
    "invoice": cmd_invoice,
    "report": cmd_report,
}


# ---------------------------------------------------------------- entry point


def _write_stdout(text: str) -> None:
    stream = sys.stdout
    buffer = getattr(stream, "buffer", None)
    if buffer is not None:
        buffer.write(text.encode("utf-8"))
        buffer.flush()
    else:
        stream.write(text)
        stream.flush()


def _silence_stdout() -> None:
    try:
        devnull = os.open(os.devnull, os.O_WRONLY)
        os.dup2(devnull, sys.stdout.fileno())
    except (OSError, ValueError, AttributeError, io.UnsupportedOperation):
        pass


def main(argv: Optional[Sequence[str]] = None) -> int:
    if argv is None:
        argv = sys.argv[1:]
    try:
        args = parse_args(list(argv))
        files = _COMMANDS[args.command][0]
        data = _Data(args.directory, files)
        output = _HANDLERS[args.command](data, args)
    except CliError as exc:
        sys.stderr.write("stockroom: %s\n" % exc.message)
        return exc.code
    try:
        if output:
            _write_stdout(output)
    except BrokenPipeError:
        _silence_stdout()
    return 0

